CHANGELOG = '## [0.255.0] - the exploded axonometric draws a stair as its treads\n\n**The factory\'s roadmap 293, its next step.** The walker, 2026-10-21, of 0.254.0\'s drawing: "draw the stairs as treads\nnext". 0.254.0 drew a stair as its footprint, an ascent line and dashed alignment columns: where a stair goes, not\nwhat it is.\n\n### Changed\n- **A flight is drawn as its treads and turn landings**: every walking surface `stairwell.ascent_surfaces` says the\n  builder builds -- the headroom gate\'s copy of `Builder._stairs`, held to it by `test_headroom.py`, so the drawing\n  and that gate read one stair -- on the storey the flight climbs from, at its true rise. A leg the builder fills\n  solid (`flight_solid_under`) stands its treads to that floor; one open beneath draws them one riser thick; a\n  switchback\'s turn landing is one riser thick, as `Builder._stairs` stands it, where the first draft stood it as a\n  column 3.6 m tall at the head of office\'s stair. Tread sides are drawn without seams, so a flight\'s side reads as\n  one stepped stringer and only the nosings are edged. Full height, not cut at the plan cut: the stair is what joins\n  the storeys.\n- **The ascent line is a leader**, dashed, from a flight\'s head across the exploded gap to its landing on the storey\n  above; the alignment columns stay.\n- **Each tread and landing carries what it is drawn**: `data-tread` or `data-landing` (`<stair>:<storey>: <k>`),\n  `data-top` (the surface\'s world height), `data-at` and `data-rise` (metres from its base to its top).\n\n### Tests\n- **test_axonometric.py**, three more: a flight is drawn as the treads the builder builds -- every surface of every\n  stair in office and deli_a03, at its own height and place, and nothing else, office\'s turn landing among them; a\n  landing is a plate and a solid flight stands on its floor (office\'s landing one riser, each of its first leg\'s\n  treads standing on storey 0\'s floor); a stair moved moves its treads. On 0.254.0 the three fail on behaviour and the\n  file\'s other eight pass (the factory\'s `patches/dc_axo_treads/prove_tests_on_0254.out.txt`).\n\n### Measured, kept\n- Frames of office -- whole and its stair, cropped -- deli_a03 and cbp_town_finale (the factory\'s\n  `patches/dc_axo_treads/axo_*.png`, `svg_png.py` and `crop_svg.py`).\n- **Left** (the factory\'s roadmap 293): ramps, platforms and fire escapes in either drawing; a solid leg\'s fill drawn\n  to its own storey\'s floor where the builder carries a cut switchback\'s second leg down to the stair\'s lowest\n  (`flight_solid_base`) -- in an exploded drawing that floor is a gap away; where a reviewer finds the drawing beside\n  a level.\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.254.0', 'Deli Counter 0.255.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
